          [{"id": "q-45-2", "type": "exact", "question": "Which Metasploit command-line utility is used to generate standalone shellcode, executables, and reverse shell payloads in various formats?",
            "visualSlots": "_ _ _ _ _ _ _ _", "acceptedAnswers": ["msfvenom"], "caseSensitive": False, "trimWhitespace": True, "hint": "msf followed by venom.", "explanation": "msfvenom combines the legacy msfpayload and msfencode tools into a unified payload generator."}]
